import {requestIdentity,sha256} from './geodata.mjs';
const clone=x=>structuredClone(x),stable=requestIdentity,freeze=x=>{if(x&&typeof x==='object'){Object.values(x).forEach(freeze);Object.freeze(x);}return x;};
export const VEHICLE_PROFILE=freeze({format:'aeris-vehicle-profile',schemaVersion:1,id:'aeris-copter471-loopback',version:'1.0.0',simulation:true,label:'ArduCopter 4.7.1 · loopback SITL',target:{firmware:'4.7.1',autopilot:3,vehicleType:2,component:1,encoding:'ardupilot-c-cast'},freshnessMs:30000,parameters:[{name:'FS_GCS_ENABLE',expected:1,type:2,unit:'enum'},{name:'FS_GCS_TIMEOUT',expected:5,type:9,unit:'s'},{name:'FS_OPTIONS',expected:16,type:6,unit:'bitmask'},{name:'MAV_GCS_SYSID',expected:255,type:4,unit:'system-id'}],missionScope:{world:'aeris-flat-world-v1',commands:[16,22,178,206,2001,20],envelopes:['aeris-qgc-run','aeris-survey-run','aeris-survey']},provenance:{baseline:'evidence/review04/final-runtime.json',definition:'PROFILE05 engineering test policy, observed four-value/types baseline; not manufacturer defaults',protocol:'research/vehicle-profile-20261012/sources.json'},scope:'Simulator-only four-parameter comparison; no complete aircraft/payload/RTK/battery/geofence or HeraHub acceptance.'});
export const PROFILE_SHA256='c4f28187ea445df1e5779b099dd90a3c324e38b8710a990c75c314f86125306a';
export const PROFILE_REF=freeze({id:VEHICLE_PROFILE.id,version:VEHICLE_PROFILE.version,sha256:PROFILE_SHA256});
export const CONFIGURATION_NAMES=freeze(VEHICLE_PROFILE.parameters.map(p=>p.name));
const same=(a,b)=>stable(a)===stable(b),validAge=a=>Number.isFinite(a)&&a>=0&&a<=VEHICLE_PROFILE.freshnessMs,validTime=s=>typeof s==='string'&&Number.isFinite(Date.parse(s)),validVehicle=v=>!!v&&Number.isInteger(v.system)&&v.system>=1&&v.system<=255&&v.component===1;
export function assertProfileReference(ref=PROFILE_REF){if(!ref||!same(ref,PROFILE_REF))throw Error('Profile/version/hash chưa được hỗ trợ.');return ref;}
export function evaluateConfiguration(observation,{sessionId=null,vehicle=null,selection=PROFILE_REF}={}){
 const checks=[];const add=(id,status,reason,expected=null,observed=null,unit=null)=>checks.push({id,status,pass:status==='MATCH',reason,expected,observed,unit});const known=same(selection,PROFILE_REF);add('profile-reference',known?'MATCH':'UNSUPPORTED',known?'Profile đã khóa phiên bản/hash.':'Profile/version/hash chưa hỗ trợ.',PROFILE_REF,selection);
 const exists=!!observation,identity=exists&&observation.format==='aeris-configuration-observation'&&observation.version===1&&observation.simulation===true&&typeof observation.id==='string'&&observation.id.length>0&&typeof sessionId==='string'&&sessionId.length>0&&observation.sessionId===sessionId&&validVehicle(vehicle)&&same(observation.vehicle,vehicle)&&observation.autopilot===3&&observation.vehicleType===2&&validTime(observation.startedAtUTC)&&validTime(observation.completedAtUTC)&&Date.parse(observation.completedAtUTC)>=Date.parse(observation.startedAtUTC);add('aircraft-session',!exists?'MISSING':identity?'MATCH':'MISMATCH',!exists?'Chưa đọc cấu hình trong phiên này.':identity?'Nguồn autopilot và phiên khớp.':'Cấu hình không thuộc aircraft/phiên hiện tại.',{sessionId,vehicle},exists?{sessionId:observation.sessionId,vehicle:observation.vehicle}:null);
 const invalidated=observation?.invalidated??null;add('observation-validity',invalidated?'INVALIDATED':exists?'MATCH':'MISSING',invalidated?'Cần đọc lại: '+invalidated:exists?'Không có gián đoạn/thay đổi đã quan sát.':'Cần đọc cấu hình mới.');
 const fw=observation?.firmware,fwOK=fw&&Number.isInteger(fw.flightSwVersion)&&fw.flightSwVersion>=0&&fw.flightSwVersion<=0xffffffff&&(fw.flightSwVersion>>>8)===0x040701&&fw.version==='4.7.1'&&fw.encoding==='ardupilot-c-cast'&&validTime(fw.observedAtUTC)&&Date.parse(fw.observedAtUTC)>=Date.parse(observation.startedAtUTC)&&Date.parse(fw.observedAtUTC)<=Date.parse(observation.completedAtUTC);add('firmware',!fw?'MISSING':!fwOK?'MISMATCH':!validAge(fw.ageMs)?'STALE':'MATCH',!fw?'Chưa có firmware mới.':!fwOK?'Firmware/encoding ngoài profile.':!validAge(fw.ageMs)?'Firmware quá cũ hoặc thời gian không hợp lệ.':'Firmware/encoding khớp.',VEHICLE_PROFILE.target.firmware,fw?.version??null);
 for(const p of VEHICLE_PROFILE.parameters){const v=observation?.parameters?.[p.name],shape=v&&Number.isFinite(v.value)&&Number.isInteger(v.type)&&Number.isInteger(v.index)&&v.index>=0&&v.index<=65535&&validTime(v.observedAtUTC)&&Date.parse(v.observedAtUTC)>=Date.parse(observation.startedAtUTC)&&Date.parse(v.observedAtUTC)<=Date.parse(observation.completedAtUTC),status=!v?'MISSING':!shape||v.value!==p.expected||v.type!==p.type?'MISMATCH':!validAge(v.ageMs)?'STALE':'MATCH';add(p.name,status,status==='MISSING'?'Chưa đọc tham số.':status==='MISMATCH'?'Giá trị/kiểu khác profile.':status==='STALE'?'Tham số quá cũ hoặc thời gian không hợp lệ.':'Giá trị/kiểu khớp.',{value:p.expected,type:p.type},v?{value:v.value,type:v.type,ageMs:v.ageMs}:null,p.unit);}
 const state=!known?'UNSUPPORTED':!exists?'NOT_OBSERVED':invalidated?'INVALIDATED':checks.some(c=>c.status==='MISMATCH')?'MISMATCH':checks.some(c=>c.status==='MISSING')?'INCOMPLETE':checks.some(c=>c.status==='STALE')?'STALE':'MATCH';return {format:'aeris-profile-comparison',version:1,simulation:true,profile:clone(selection),state,pass:checks.every(c=>c.pass),checks,freshnessMs:VEHICLE_PROFILE.freshnessMs,scope:VEHICLE_PROFILE.scope};
}
export function makeProfileSnapshot(observation,context){return {format:'aeris-profile-snapshot',version:1,simulation:true,definition:clone(VEHICLE_PROFILE),profile:clone(PROFILE_REF),context:clone(context),observation:clone(observation),comparison:evaluateConfiguration(observation,context)};}
export async function validateProfileSnapshot(snapshot,{sessionId,vehicle}={}){if(snapshot?.format!=='aeris-profile-snapshot'||snapshot.version!==1||snapshot.simulation!==true||!same(snapshot.definition,VEHICLE_PROFILE)||!same(snapshot.profile,PROFILE_REF)||await sha256(stable(snapshot.definition))!==PROFILE_SHA256||!same(snapshot.context,{sessionId,vehicle})||!same(snapshot.comparison,evaluateConfiguration(snapshot.observation,snapshot.context)))throw Error('Snapshot profile/hash/phiên/kết luận không hợp lệ.');return clone(snapshot);}

export function assertMissionProfile(compiled){const source=compiled?.sourceRequest??compiled?.sourcePackage;if(compiled?.worldId!==VEHICLE_PROFILE.missionScope.world||!VEHICLE_PROFILE.missionScope.envelopes.includes(source?.format)||!Array.isArray(compiled.items)||compiled.items.some(i=>!VEHICLE_PROFILE.missionScope.commands.includes(i.command)))throw Error('Nhiệm vụ ngoài phạm vi profile đã khóa.');}
